const verdictOf = r => r.mc ? "OK" : r.v;

const order = ["OK","VERDAECHTIG","FAKE","UNKLAR"];
let labels = {FAKE:t("verdict.fake"), VERDAECHTIG:t("verdict.suspicious"), OK:t("verdict.ok"), UNKLAR:t("verdict.unclear")};

